18	use crate::view::KvView;
19	
20	/// Broadcast capacity for the opt-in KV-event feed. Generous: the scheduler
21	/// drains it every step, but a step can register/evict many blocks, and a
22	/// dropped event silently desyncs the router's prefix tree. Only allocated on
23	/// the [`BlockPool::with_events`] path.
24	const KV_EVENT_CHANNEL_CAPACITY: usize = 65_536;
25	
26	/// Logical KV block pool: a `BlockManager` plus the reserved padding block.
27	///
28	/// Owns no GPU memory — the physical layout (full-attention `KvBuffer`,
29	/// MLA dual ckv/kpe buffers, ...) lives with the consumer and is indexed
30	/// by the block IDs this pool hands out.
31	pub struct BlockPool {
32	    block_manager: BlockManager<()>,
33	    block_size: usize,
34	    padding_block_id: usize,
35	}
