577	    // ── Queries ────────────────────────────────────────────────────────
578	
579	    /// Tokens with KV already computed.
580	    pub fn kv_position(&self) -> usize {
581	        self.seq.kv_position()
582	    }
583	
584	    pub fn is_complete(&self) -> bool {
585	        self.seq.is_complete()
586	    }
587	
588	    pub fn generated_tokens(&self) -> usize {
589	        self.seq.generated_tokens()
590	    }
591	
592	    /// Physical blocks currently held by this request, including registered,
593	    /// staged, and eagerly allocated dangling blocks.
594	    pub fn resident_blocks(&self) -> usize {
595	        self.seq.assigned_blocks() + self.seq.staged_blocks() + self.seq.unassigned_blocks()
596	    }
597	
598	    /// Physical page IDs assigned to this request, in sequence order.
599	    /// Includes every block the request currently holds — which can be one
600	    /// more than the KV tokens need (see `step_page_indices`).
601	    fn page_indices(&self) -> Vec<i32> {
602	        self.seq
603	            .inner()
604	            .assignments()
605	            .all_block_ids()
606	            .map(|&id| id as i32)
607	            .collect()
608	    }
609	
610	    /// Physical pages covering the KV tokens currently committed to this
611	    /// request, in logical sequence order.
612	    pub fn current_page_indices(&self) -> Vec<i32> {
613	        let mut pages = self.page_indices();
614	        pages.truncate(self.seq.kv_position().div_ceil(self.seq.block_size()));
615	        pages
616	    }
617	
618	    /// Page IDs covering exactly the KV tokens present after this step
619	    /// appends `new_tokens` (`kv_position + new_tokens`). `page_indices()`
620	    /// can hold one block more: kvbm's `schedule_decode` eagerly allocates
621	    /// the next generation block whenever this step's token fills the last
622	    /// slot of the current block. Page tables built from the raw list make
623	    /// the kernel see a longer sequence than exists — use this for any
624	    /// per-step page row handed to a forward pass.
625	    pub fn step_page_indices(&self, new_tokens: usize) -> Vec<i32> {
626	        assert!(new_tokens > 0, "a forward step appends at least one token");
627	        let kv_tokens = self.seq.kv_position() + new_tokens;
628	        let mut pages = self.page_indices();
629	        pages.truncate(kv_tokens.div_ceil(self.seq.block_size()));
630	        pages
631	    }
632	
633	    // ── KV offload bridge ──────────────────────────────────────────────
634	
635	    /// Content hashes of every *full* prompt block, in prompt order.
636	    ///
637	    /// These are the keys the KV-offload connector queries the CPU tier with,
638	    /// so they must be identical across any two requests sharing a prefix.
639	    /// They are kvbm's lineage-based [`SequenceHash`], which is exactly that:
640	    /// position + content + parent fragment, so block `i` of prompt `P` hashes
641	    /// the same no matter which request computed it.
642	    #[cfg(test)]
643	    fn prompt_block_hashes(&self) -> Vec<[u8; 16]> {
644	        self.seq
645	            .inner()
646	            .sequence()
647	            .all_sequence_hashes()
648	            .iter()
649	            .map(sequence_hash_bytes)
650	            .collect()
651	    }
652	
653	    /// `(page_id, content_hash)` for every block currently assigned to this
654	    /// request, in prompt order. Drives the offload save once a block seals;
655	    /// the first [`prefix_matched_blocks`](Self::prefix_matched_blocks) entries
656	    /// are GPU-hit reuse (already resident) and are normally skipped.
657	    pub fn assigned_block_hashes(&self) -> Vec<(i32, [u8; 16])> {
658	        self.seq
659	            .inner()
660	            .assignments()
661	            .assigned_iter()
662	            .map(|(&id, block)| (id as i32, sequence_hash_bytes(&block.sequence_hash())))
663	            .collect()
664	    }
665	
666	    /// Strong pins for every block currently assigned to this request, aligned
667	    /// 1:1 (same order) with [`assigned_block_hashes`](Self::assigned_block_hashes).
668	    ///
669	    /// An offload save's GPU→CPU copy runs asynchronously after the save is
670	    /// submitted; holding the matching [`KvBlockGuard`] keeps that block out of
671	    /// the free/inactive pool until the copy lands, so a later request can't be
672	    /// allocated the same slot and overwrite it mid-copy. Drop the guard once
673	    /// the save reports done.
674	    pub fn assigned_block_guards(&self) -> Vec<KvBlockGuard> {
675	        self.seq
676	            .inner()
677	            .assignments()
678	            .assigned_iter()
679	            .map(|(_, block)| KvBlockGuard(block.clone()))
680	            .collect()
681	    }
682	
683	    /// Number of leading blocks reused from the GPU prefix cache.
684	    pub fn prefix_matched_blocks(&self) -> usize {
685	        self.seq.inner().prefix_matched_blocks()
686	    }
687	
688	    /// Blocks this request has registered (made cacheable) since the last call,
689	    /// in the u64 hash space a KV-router consumes plus the kvbm lineage hash.
690	    ///
691	    /// A block becomes reusable by other requests once it is *registered*
692	    /// (assigned an `ImmutableBlock`), which lags sealing the token block by a
693	    /// step. Diffs the registered count against an internal cursor and returns
694	    /// the new run in sequence order; prefix-cache hits are skipped (see
695	    /// [`Self::emitted_blocks`]). Empty when nothing new registered this step.
696	    pub fn take_newly_registered_blocks(&mut self) -> Vec<RegisteredBlock> {
697	        let registered = self.seq.assigned_blocks();
698	        if registered <= self.emitted_blocks {
699	            return Vec::new();
700	        }
701	        let blocks = self.seq.inner().sequence().blocks();
702	        debug_assert!(
703	            registered <= blocks.len(),
704	            "registered blocks ({registered}) exceed sealed token blocks ({})",
705	            blocks.len()
706	        );
707	        let new = blocks[self.emitted_blocks..registered]
708	            .iter()
709	            .map(|b| RegisteredBlock {
710	                plh: b.kvbm_sequence_hash().as_u128(),
711	                sequence_hash: b.sequence_hash(),
712	                tokens_hash: b.block_hash(),
713	                parent_sequence_hash: b.parent_sequence_hash(),
714	            })
715	            .collect();
716	        self.emitted_blocks = registered;
717	        new
718	    }
719	}
720	
721	/// One full KV block a request just registered, ready to become a KV-router
722	/// store event. `sequence_hash`/`tokens_hash`/`parent_sequence_hash` are the
723	/// router's u64 hashes (`dynamo_tokens::TokenBlock` accessors, identical by
724	/// construction to what the router recomputes); `plh` is the engine's 128-bit
725	/// lineage hash, kept only to correlate an eviction event (which carries the
726	/// lineage hash) back to `sequence_hash`.
727	#[derive(Clone, Copy, Debug)]
728	pub struct RegisteredBlock {
729	    pub plh: u128,
730	    pub sequence_hash: u64,
731	    pub tokens_hash: u64,
732	    pub parent_sequence_hash: Option<u64>,
733	}
734	
735	/// Pack a kvbm [`SequenceHash`] (lineage hash) into the 16-byte content key the
736	/// offload tier addresses blocks by. Big-endian for a stable on-wire ordering.
737	fn sequence_hash_bytes(hash: &SequenceHash) -> [u8; 16] {
738	    hash.as_u128().to_be_bytes()
739	}
