745	    /// The offload CPU-tier query keys are `prompt_block_hashes`. The whole
746	    /// load path is built on these being identical for any two requests that
747	    /// share a prefix (and diverging the moment content does) — otherwise a
748	    /// warm block saved by one request would never match the next. Guard it.
749	    #[test]
750	    fn prompt_block_hashes_stable_across_shared_prefix() {
751	        let pool = BlockPool::new(16, 256).unwrap();
752	        let shared: Vec<u32> = (0..48).map(|i| 1000 + i).collect(); // 3 full blocks
753	        let mut a_tokens = shared.clone();
754	        a_tokens.extend((0..16).map(|i| 7000 + i)); // 4th block diverges
755	        let mut b_tokens = shared.clone();
756	        b_tokens.extend((0..16).map(|i| 9000 + i));
757	
758	        let a = pool.new_request(a_tokens, 8, None);
759	        let b = pool.new_request(b_tokens, 8, None);
760	        let ha = a.prompt_block_hashes();
761	        let hb = b.prompt_block_hashes();
762	
763	        assert_eq!(ha.len(), 4, "64 tokens / 16 = 4 full blocks");
764	        assert_eq!(hb.len(), 4);
765	        assert_eq!(ha[..3], hb[..3], "shared prefix must hash identically");
766	        assert_ne!(ha[3], hb[3], "divergent block must hash differently");
767	        assert!(ha.iter().all(|h| *h != [0u8; 16]), "hashes are non-trivial");
768	
769	        // A different LoRA salt must poison the match — same tokens, new keys.
770	        let c = pool.new_request(shared, 8, Some("adapter-x"));
771	        assert_ne!(
772	            c.prompt_block_hashes()[0],
773	            ha[0],
774	            "salt (lora) must scope the prefix cache"
775	        );
776	    }
