133	    /// Return active prompt-prefix hashes without promoting inactive entries or
134	    /// keeping the matched blocks alive.
135	    pub fn active_prefix_hashes(
136	        &self,
137	        prompt_tokens: Vec<u32>,
138	        lora_name: Option<&str>,
139	    ) -> Vec<[u8; 16]> {
140	        let num_input = prompt_tokens.len();
141	        let request = self.new_request(prompt_tokens, 0, lora_name);
142	        let hashes = request.seq.inner().sequence().all_sequence_hashes();
143	        let cacheable = num_input.saturating_sub(1) / self.block_size;
144	        let active = self.block_manager.active_prefix_len(&hashes).min(cacheable);
145	        hashes[..active].iter().map(sequence_hash_bytes).collect()
146	    }
