260	/// A prompt's prefix resolved against the GPU cache, ready to drive a CPU-tier
261	/// prefetch. Holds every GPU-hit (and, after commit, CPU-loaded) block so they
262	/// can't be evicted while the load is in flight and before the request prefills.
263	pub struct PrefixProbe {
264	    /// Content hashes of every complete prompt block, in order (native form).
265	    seq_hashes: Vec<SequenceHash>,
266	    /// Length of the contiguous GPU-resident prefix.
267	    gpu_hit: usize,
268	    /// Reuse cap: blocks past this are never matched (the final chunk forwards).
269	    cacheable: usize,
270	    /// Tokens represented by one complete KV block.
271	    block_size: usize,
272	    /// Strong refs keeping matched/loaded blocks resident until prefill.
273	    held: Vec<ImmutableBlock<()>>,
274	}
275	
276	impl PrefixProbe {
277	    /// Blocks already resident in GPU HBM (the existing prefix-cache hit).
278	    pub fn gpu_hit_blocks(&self) -> usize {
279	        self.gpu_hit
280	    }
281	
282	    /// Total blocks this probe holds: the GPU-hit prefix plus any committed from
283	    /// a CPU-tier load. They are already out of the free pool and become the
284	    /// request's cached prefix at prefill, so admission credits them against the
285	    /// request's block need (avoiding a double-count against `available_blocks`).
286	    pub fn held_blocks(&self) -> usize {
287	        self.held.len()
288	    }
289	
290	    /// Complete prefix blocks eligible for request reuse.
291	    ///
292	    /// This is capped by the final-token rule even if a caller extended the
293	    /// probe with additional loaded blocks.
294	    pub fn reusable_blocks(&self) -> usize {
295	        self.held.len().min(self.cacheable)
296	    }
297	
298	    /// Returns the lineage hash identifying the complete reusable prefix ending
299	    /// at `boundary_tokens`.
300	    ///
301	    /// `boundary_tokens` is measured in tokens. For example,
302	    /// with a 16-token block size, `boundary_hash(32)` identifies the token
303	    /// prefix `[0, 32)`. The returned hash covers the full prefix lineage,
304	    /// rather than only the contents of the final block.
305	    ///
306	    /// Returns `None` when the boundary is zero, is not block-aligned, or
307	    /// exceeds the reusable prefix.
308	    pub fn boundary_hash(&self, boundary_tokens: usize) -> Option<[u8; 16]> {
309	        if boundary_tokens == 0 || !boundary_tokens.is_multiple_of(self.block_size) {
310	            return None;
311	        }
312	        let block_count = boundary_tokens / self.block_size;
313	        if block_count > self.reusable_blocks() {
314	            return None;
315	        }
316	        self.seq_hashes
317	            .get(block_count - 1)
318	            .map(sequence_hash_bytes)
319	    }
320	
321	    /// Content hashes to query the CPU tier with: the blocks past the GPU hit,
322	    /// capped at the reuse boundary. Empty when the GPU hit already covers
323	    /// every reusable block (nothing to load — prefill normally).
324	    pub fn cpu_query_hashes(&self) -> Vec<Vec<u8>> {
325	        if self.gpu_hit >= self.cacheable {
326	            return Vec::new();
327	        }
328	        self.seq_hashes[self.gpu_hit..self.cacheable]
329	            .iter()
330	            .map(|h| sequence_hash_bytes(h).to_vec())
331	            .collect()
332	    }
333	
334	    /// Number of blocks [`Self::cpu_query_hashes`] covers, without
335	    /// materializing the hash bytes. Callers substituting their own key
336	    /// scheme (vLLM-compat P/D) slice their chain to exactly this window.
337	    pub fn cpu_query_window(&self) -> usize {
338	        self.cacheable.saturating_sub(self.gpu_hit)
339	    }
340	}
