425	    /// Returns the lineage hash identifying the registered prefix ending at
426	    /// `boundary_tokens`.
427	    ///
428	    /// `boundary_tokens` must be a non-zero multiple of the KV `block_size`,
429	    /// and be no more than the number of blocks already registered by this request;
430	    /// otherwise this method returns `None`.
431	    pub fn registered_boundary_hash(&self, boundary_tokens: usize) -> Option<[u8; 16]> {
432	        let block_size = self.seq.block_size();
433	        if boundary_tokens == 0 || !boundary_tokens.is_multiple_of(block_size) {
434	            return None;
435	        }
436	        let block_count = boundary_tokens / block_size;
437	        if block_count > self.seq.assigned_blocks() {
438	            return None;
439	        }
440	        self.seq
441	            .inner()
442	            .sequence()
443	            .all_sequence_hashes()
444	            .get(block_count - 1)
445	            .map(sequence_hash_bytes)
446	    }
