618	    /// Page IDs covering exactly the KV tokens present after this step
619	    /// appends `new_tokens` (`kv_position + new_tokens`). `page_indices()`
620	    /// can hold one block more: kvbm's `schedule_decode` eagerly allocates
621	    /// the next generation block whenever this step's token fills the last
622	    /// slot of the current block. Page tables built from the raw list make
623	    /// the kernel see a longer sequence than exists — use this for any
624	    /// per-step page row handed to a forward pass.
625	    pub fn step_page_indices(&self, new_tokens: usize) -> Vec<i32> {
626	        assert!(new_tokens > 0, "a forward step appends at least one token");
627	        let kv_tokens = self.seq.kv_position() + new_tokens;
628	        let mut pages = self.page_indices();
629	        pages.truncate(kv_tokens.div_ceil(self.seq.block_size()));
