635	    /// Content hashes of every *full* prompt block, in prompt order.
636	    ///
637	    /// These are the keys the KV-offload connector queries the CPU tier with,
638	    /// so they must be identical across any two requests sharing a prefix.
639	    /// They are kvbm's lineage-based [`SequenceHash`], which is exactly that:
640	    /// position + content + parent fragment, so block `i` of prompt `P` hashes
641	    /// the same no matter which request computed it.
642	    #[cfg(test)]
643	    fn prompt_block_hashes(&self) -> Vec<[u8; 16]> {
644	        self.seq
645	            .inner()
646	            .sequence()
647	            .all_sequence_hashes()
648	            .iter()
649	            .map(sequence_hash_bytes)
650	            .collect()
651	    }
